"""Small find/bfs -printf format renderer."""
import datetime
import grp
import os
import pwd
import stat as statmod
import time


def _mode_type(mode):
    if statmod.S_ISREG(mode): return 'f'
    if statmod.S_ISDIR(mode): return 'd'
    if statmod.S_ISLNK(mode): return 'l'
    if statmod.S_ISFIFO(mode): return 'p'
    if statmod.S_ISSOCK(mode): return 's'
    if statmod.S_ISCHR(mode): return 'c'
    if statmod.S_ISBLK(mode): return 'b'
    return 'D'


def _filesystem(path):
    """Best-effort Linux filesystem name, matching %F."""
    try:
        best = ('', '')
        with open('/proc/mounts', encoding='utf-8', errors='replace') as mounts:
            for line in mounts:
                fields = line.split()
                if len(fields) < 3: continue
                mount = fields[1].replace('\\040', ' ')
                if (path == mount or path.startswith(mount.rstrip('/') + '/')) and len(mount) > len(best[0]):
                    best = (mount, fields[2])
        return best[1] or 'unknown'
    except OSError:
        return 'unknown'


def render_printf(path, fmt, st=None, root=None, depth=None):
    """Render a bfs printf format for path; st may be os.stat_result."""
    if st is None:
        try: st = os.lstat(path)
        except OSError: return ''
    path = os.fspath(path)
    base = os.path.basename(path.rstrip(os.sep)) or os.sep
    parent = os.path.dirname(path.rstrip(os.sep)) or '.'
    if root is None: root = path
    if depth is None:
        depth = 0 if path == root else len(os.path.relpath(path, root).split(os.sep))
    typ = _mode_type(st.st_mode)
    try: target = os.readlink(path) if typ == 'l' else ''
    except OSError: target = ''
    vals = {
        'p': path, 'f': base, 'h': parent, 'H': root,
        'P': path[len(root):].lstrip(os.sep) if path != root else '',
        'y': typ, 'Y': typ, 's': str(st.st_size), 'b': str((st.st_blocks if hasattr(st,'st_blocks') else (st.st_size+511)//512)),
        'k': str(((st.st_blocks if hasattr(st,'st_blocks') else (st.st_size+511)//512)+1)//2),
        'm': format(statmod.S_IMODE(st.st_mode), 'o'), 'U': str(st.st_uid), 'G': str(st.st_gid),
        'i': str(st.st_ino), 'n': str(st.st_nlink), 'd': str(depth), 'l': target,
    }
    try: vals['u'] = pwd.getpwuid(st.st_uid).pw_name
    except KeyError: vals['u'] = str(st.st_uid)
    try: vals['g'] = grp.getgrgid(st.st_gid).gr_name
    except KeyError: vals['g'] = str(st.st_gid)
    vals['F'] = _filesystem(os.path.abspath(path))
    vals['D'] = str(os.major(st.st_dev)) + ',' + str(os.minor(st.st_dev))
    out=[]; i=0
