            i+=1; c=fmt[i]
            out.append({'a':'\a','b':'\b','c':'','f':'\f','n':'\n','r':'\r','t':'\t','v':'\v','\\':'\\'}.get(c,c)); i+=1; continue
        if fmt[i] != '%' or i+1 >= len(fmt): out.append(fmt[i]); i+=1; continue
        i+=1
        if fmt[i] == '%': out.append('%'); i+=1; continue
        # bfs time directives use %A/%B/%C followed by an optional format modifier.
        if fmt[i] in 'aABctT':
            kind=fmt[i]; i+=1
            mod='';
            if i<len(fmt) and fmt[i] in '@+': mod=fmt[i]; i+=1
            attr={'a':'st_atime','A':'st_atime','c':'st_ctime','C':'st_ctime','t':'st_mtime','T':'st_mtime'}[kind]
            sec=getattr(st,attr); ns=getattr(st, attr+'_ns', int(sec*1e9))%1000000000
            fraction=f'{ns:09d}0'
            if mod=='@': value=f'{int(sec)}.{fraction}'
            elif mod=='+': value=time.strftime('%Y-%m-%d+%H:%M:%S',time.localtime(sec))+f'.{fraction}'
            else: value=time.strftime('%a %b %e %H:%M:%S',time.localtime(sec))+f'.{fraction} '+time.strftime('%Y',time.localtime(sec))
            out.append(value); continue
        c=fmt[i]; i+=1
        out.append(vals.get(c, '%' + c))
    return ''.join(out)

